def min_moves_to_a_good_string(s):
    n = len(s)
    if n == 1:
        return 0 if s == 'a' else 1

    left_half = s[:n//2]
    right_half = s[n//2:]

    if left_half == right_half:
        return min_moves_to_a_good_string(left_half)

    left_moves = min_moves_to_a_good_string(left_half)
    right_moves = min_moves_to_a_good_string(right_half)

    return 1 + min(left_moves, right_moves)

