def construct_palindrome(N, P):
    if N == P:
        return "impossible" if N % 2 == 1 else "ab" * (N // 2)

    if N % P != 0:
        return "impossible"

    half = N // 2
    if half % P != 0:
        return "impossible"

    half_period = half // P
    if half_period % 2 == 0:
        return "impossible"

    half_str = "ab" * (half_period // 2) + "a"
    return half_str + half_str[::-1]

