def max_score(matrix):
    m, n = len(matrix), len(matrix[0])

    # Toggle rows to ensure the first column has more 1s
    for i in range(m):
        if matrix[i][0] == 0:
            for j in range(n):
                matrix[i][j] = 1 - matrix[i][j]

    # Toggle columns to ensure each column has more 1s
    for j in range(1, n):
        count_ones = sum(matrix[i][j] for i in range(m))
        if count_ones < m - count_ones:
            for i in range(m):
                matrix[i][j] = 1 - matrix[i][j]

    # Calculate the score
    score = 0
    for i in range(m):
        row_value = 0
        for j in range(n):
            row_value = (row_value << 1) | matrix[i][j]
        score += row_value

    return score

