def longest_subsequence(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Initialize the dp array where dp[i] will store the length of the longest subsequence ending at index i
    dp = [1] * n

    # Iterate through the array to fill the dp array
    for i in range(1, n):
        for j in range(i):
            if (arr[i] ^ arr[j]) >= (arr[j] ^ arr[j-1]) if j > 0 else 0:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the longest subsequence will be the maximum value in the dp array
    return max(dp)

