import sys

def can_ada_win(board):
    n = len(board)
    pawns = [i for i in range(n) if board[i] == 'P']

    def is_valid_move(pawn, move):
        return 0 <= pawn + move < n and board[pawn + move] == '.'

    def can_move(pawn):
        return is_valid_move(pawn, -1) or is_valid_move(pawn, -2)

    def can_ada_win_from(pawn):
        if not can_move(pawn):
            return False
        for move in [-1, -2]:
            if is_valid_move(pawn, move):
                board[pawn] = '.'
                board[pawn + move] = 'P'
                if not can_ada_win_from(pawn + move):
                    board[pawn] = 'P'
                    board[pawn + move] = '.'
                    return True
                board[pawn] = 'P'
                board[pawn + move] = '.'
        return False

    for pawn in pawns:
        if can_ada_win_from(pawn):
            return True
    return False

