import sys

def find_collision(N, K, x, y):
    # Calculate the number of full cycles the ball will complete
    full_cycles = min(x, y, N - x, N - y)
    K -= full_cycles * 4

    # If K is zero, the ball has stopped at a corner
    if K == 0:
        if x == y:
            return N, N
        elif x == N - y:
            return N, 0
        elif x == y:
            return 0, N
        else:
            return 0, 0

    # Determine the direction of the ball
    if x < y:
        if x < N - y:
            return N, y + K
        else:
            return x - K, N
    else:
        if x < N - y:
            return x - K, 0
        else:
            return N, y + K

def main():
