def count_special_numbers(N):
    def is_special(n):
        product = 1
        while n > 0:
            digit = n % 10
            if digit == 1:
                return False
            if digit > 1:
                return False
            product *= digit
            n //= 10
        return product == n

    def count_partial_special(n, current, count):
        if n == 0:
            return count
        if n < 0:
            return count
        if current > 0:
            count += 1
        for i in range(1, 10):
            count = count_partial_special(n, current * 10 + i, count)
        return count

    special_count = 0
    partial_special_count = 0

    for i in range(1, N + 1):
        if is_special(i):
            special_count += 1
        partial_special_count += count_partial_special(i, 1, 0)

    return special_count, partial_special_count

