import math
from collections import defaultdict

def gcd(a, b):
    if a == 0:
        return b
    return gcd(b % a, a)

def lcm(a, b):
    return (a * b) // gcd(a, b)

def solve(s, n):
    l = len(s)
    d = defaultdict(int)
    for i in range(l):
        d[s[i]] += 1
    ans = 0
    for i in range(1, n + 1):
        ans += d['S'] * lcm(i, l)
        ans += d['T'] * lcm(i, l // 2)
    return ans

def main():
