import sys

def max_increasing_subsequence_length(sequence):
    if not sequence:
        return 0
    length = len(sequence)
    lis = [1] * length
    for i in range(1, length):
        for j in range(i):
            if sequence[i] > sequence[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1
    return max(lis)

def find_min_m(N, A):
    max_length = max_increasing_subsequence_length(A)
    for M in range(1, N + 1):
        B = A * M
        current_length = max_increasing_subsequence_length(B)
        if current_length == max_length:
            return M

def main():
    T = int(input())
    for _ in range(T):
        N = int(input())
