    for i in range(L):
        for j in range(i, L):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

def count_operations(matrix, N):
    operations = 0
    for i in range(N):
        for j in range(N):
            if matrix[i][j] != (i * N + j + 1):
