def sieve(n):
    is_prime = [True] * (n + 1)
    p = 2
    while (p * p <= n):
        if (is_prime[p] == True):
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    return [p for p in range(2, n + 1) if is_prime[p]]

def count_prime_pairs(n, primes):
    count = 0
    for p in primes:
        if p > n:
            break
        q = (n - p) // 2
        if (n - p) % 2 == 0 and q in primes:
            count += 1
    return count

def main():
    T = int(input())
    primes = sieve(10000)
    for _ in range(T):
        N = int(input())
        result = count_prime_pairs(N, primes)
        print(result)

