def min_lcs(n, strings):
    from functools import lru_cache
    from collections import Counter

    @lru_cache(None)
    def lcs(s1, s2):
        if not s1 or not s2:
            return 0
        if s1[-1] == s2[-1]:
            return 1 + lcs(s1[:-1], s2[:-1])
        else:
            return max(lcs(s1[:-1], s2), lcs(s1, s2[:-1]))

    min_lcs_value = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            min_lcs_value = min(min_lcs_value, lcs(strings[i], strings[j]))

    return min_lcs_value

