from collections import defaultdict

def solve(L, K):
    if K > L:
        return 0
    if K == L:
        return 1
    if K == 1:
        return L - 1

    dp = defaultdict(lambda: 0)
    dp[1] = L - 1
    for i in range(2, L + 1):
        dp[i] = dp[i - 1] + (L - i) * (i - 1)
    return dp[K]

