import sys

def expected_hearts(N, M, K, hearts):
    total_rectangles = N * M * (N + 1) * (M + 1) // 4
    heart_counts = [0] * (N * M + 1)

    for heart in hearts:
        heart_counts[heart] = 1

    for i in range(1, N * M + 1):
        if heart_counts[i] == 1:
            for j in range(1, N * M + 1):
                if heart_counts[j] == 1:
                    if i <= j:
                        for k in range(1, N + 1):
                            if i + (k - 1) * M <= j:
                                for l in range(1, M + 1):
                                    if i + (k - 1) * M + (l - 1) * N <= j:
                                        heart_counts[i + (k - 1) * M + (l - 1) * N] += 1

    expected_value = 0
    for i in range(1, N * M + 1):
        expected_value += heart_counts[i] * i

    expected_value /= total_rectangles
    return expected_value

