def solve():
    N, x = map(int, input().split())
    a = list(map(int, input().split()))
    a.sort()
    q = deque()
    ans = 0
    for i in range(N):
        while q and q[0] < i:
            q.popleft()
        if not q:
            q.append(i)
        else:
            q.append(q[0])
        while q and a[q[-1]] + x < 2 * a[i]:
