import sys
from math import gcd

def can_indulge(a, b):
    return gcd(a, b) == 1 or a % b == 0 or b % a == 0

def find_seating(n):
    chairs = list(range(1, 4*n + 1))
    selected = []

    for i in range(n):
        for chair in chairs:
            if all(not can_indulge(chair, s) for s in selected):
                selected.append(chair)
                break

    return selected

def main():
